'use strict';

// MODULES //

var rtrim = require( '@stdlib/string/right-trim' );
var repeat = require( '@stdlib/string/repeat' );
var BREAK_CLASSES = require( './break_classes.json' );


// VARIABLES //

var MAX_WIDTH = 80;


// FUNCTIONS //

/**
* Determines whether a break opportunity exists between two adjacent characters.
*
* @private
* @param {string} prev - break class of preceding character
* @param {string} next - break class of following character
* @returns {boolean} whether a break is allowed
*/
function canBreak( prev, next ) {
	if ( next === 'SP' ) {
		return false;
	}
	if ( prev === 'SP' ) {
		return true;
	}
	if ( next === 'CL' ) {
		return false;
	}
	if ( next === 'IS' ) {
		return false;
	}
	if ( prev === 'OP' ) {
		return false;
	}
	if ( next === 'QU' ) {
		return false;
	}
	if ( prev === 'QU' ) {
		return false;
	}
	if ( prev === 'HY' ) {
		return true;
	}
	return false;
}

/**
* Finds break opportunities in a string and returns an array of break unit segments.
*
* @private
* @param {string} text - input string
* @returns {StringArray} array of break unit segments
*/
function findBreakUnits( text ) {
	var segments;
	var start;
	var prev;
	var curr;
	var len;
	var i;

	len = text.length;
	if ( len === 0 ) {
		return [ '' ];
	}
	segments = [];
	start = 0;
	prev = BREAK_CLASSES[ text.charAt( 0 ) ] || 'AL';

	for ( i = 1; i < len; i++ ) {
		curr = BREAK_CLASSES[ text.charAt( i ) ] || 'AL';
		if ( canBreak( prev, curr ) ) {
			segments.push( text.substring( start, i ) );
			start = i;
		}
		prev = curr;
	}
	segments.push( text.substring( start ) );
	return segments;
}


// MAIN //

/**
* Wraps repl text.
*
* @param {string} text - unwrapped single-paragraph text
* @param {NonNegativeInteger} indent - number of leading spaces per output line
* @param {PositiveInteger} [maxWidth=80] - total line width limit
* @returns {string} wrapped text with indent applied to each line
*
* @example
* var out = wrap( 'This is a short line.', 4 );
* // returns '    This is a short line.'
*/
function wrap( text, indent, maxWidth ) {
	var contentWidth;
	var segments;
	var prefix;
	var lines;
	var line;
	var seg;
	var i;

	if ( arguments.length < 3 ) {
		maxWidth = MAX_WIDTH;
	}
	prefix = repeat( ' ', indent );
	contentWidth = maxWidth - indent;
	if ( contentWidth <= 0 || text.length === 0 ) {
		return prefix + text;
	}
	segments = findBreakUnits( text );
	lines = [];
	line = '';

	for ( i = 0; i < segments.length; i++ ) {
		seg = segments[ i ];
		if ( seg.length === 0 ) {
			continue;
		}
		if ( line.length === 0 ) {
			line = seg;
		} else if ( rtrim( line + seg ).length <= contentWidth ) {
			line += seg;
		} else {
			lines.push( prefix + rtrim( line ) );
			if ( seg.charAt( 0 ) === ' ' ) {
				seg = seg.substring( 1 );
			}
			line = seg;
		}
	}
	if ( line.length > 0 ) {
		lines.push( prefix + rtrim( line ) );
	}
	return lines.join( '\n' );
}


// EXPORTS //

module.exports = wrap;
